package cache

import (
	"math"
	"sync/atomic"
	"time"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
)

// CacheEntry represents a complete cached request-response pair with associated metadata
type CacheEntry struct {
	RequestID    string
	RequestBody  []byte
	ResponseBody []byte
	Model        string
	Query        string
	Embedding    []float32
	Timestamp    time.Time // Creation time (when the entry was added or completed with a response)
	LastAccessAt time.Time // Last access time
	HitCount     int64     // Access count
	TTLSeconds   int       // Per-entry TTL in seconds (0 = not cached, -1 = use cache default, >0 = specific TTL)
	ExpiresAt    time.Time // Calculated expiration time based on TTL
}

// CacheBackend defines the interface for semantic cache implementations
type CacheBackend interface {
	// IsEnabled returns whether caching is currently active
	IsEnabled() bool

	// CheckConnection verifies the cache backend connection is healthy
	// Returns nil if the connection is healthy, error otherwise
	// For local caches (in-memory), this may be a no-op
	CheckConnection() error

	// AddPendingRequest stores a request awaiting its response. Model is an
	// exact cache partition key; entries from another model partition must
	// never be considered by lookup.
	AddPendingRequest(requestID string, model string, query string, requestBody []byte, ttlSeconds int) error

	// UpdateWithResponse completes a pending request with the received response
	UpdateWithResponse(requestID string, responseBody []byte, ttlSeconds int) error

	// AddEntry stores a complete request-response pair in the cache
	AddEntry(requestID string, model string, query string, requestBody, responseBody []byte, ttlSeconds int) error

	// FindSimilar searches for semantically similar cached requests inside the
	// exact model partition.
	// Returns the cached response, match status, and any error
	FindSimilar(model string, query string) ([]byte, bool, error)

	// FindSimilarWithThreshold searches inside the exact model partition using
	// a specific threshold.
	// This allows category-specific similarity thresholds
	// Returns the cached response, match status, and any error
	FindSimilarWithThreshold(model string, query string, threshold float32) ([]byte, bool, error)

	// LastSimilarity returns the similarity score from the most recent
	// FindSimilarWithThreshold call. Returns 0 if no lookup has been performed.
	// Used by the extproc layer to set the x-vsr-cache-similarity response header.
	LastSimilarity() float32

	// Close releases all resources held by the cache backend
	Close() error

	// GetStats provides cache performance and usage metrics
	GetStats() CacheStats
}

// SimilarityTracker provides thread-safe storage for the last similarity score.
// Embed this in cache backends to satisfy the LastSimilarity() interface method.
type SimilarityTracker struct {
	lastSimilarity uint64 // atomic; stores float32 bits
}

// StoreSimilarity records a similarity score (thread-safe).
func (t *SimilarityTracker) StoreSimilarity(similarity float32) {
	atomic.StoreUint64(&t.lastSimilarity, uint64(math.Float32bits(similarity)))
}

// LastSimilarity returns the most recently stored similarity score.
func (t *SimilarityTracker) LastSimilarity() float32 {
	bits := atomic.LoadUint64(&t.lastSimilarity)
	return math.Float32frombits(uint32(bits & 0xFFFFFFFF)) //nolint:gosec // intentional: float32 bits fit in 32 bits
}

// CacheStats holds performance metrics and usage statistics for cache operations
type CacheStats struct {
	TotalEntries    int        `json:"total_entries"`
	HitCount        int64      `json:"hit_count"`
	MissCount       int64      `json:"miss_count"`
	HitRatio        float64    `json:"hit_ratio"`
	LastCleanupTime *time.Time `json:"last_cleanup_time,omitempty"`
}

// CacheBackendType defines the available cache backend implementations
type CacheBackendType string

const (
	// InMemoryCacheType specifies the in-memory cache backend
	InMemoryCacheType CacheBackendType = "memory"

	// MilvusCacheType specifies the Milvus vector database backend
	MilvusCacheType CacheBackendType = "milvus"

	// RedisCacheType specifies the Redis vector database backend
	RedisCacheType CacheBackendType = "redis"

	// ValkeyCacheType specifies the Valkey vector database backend
	ValkeyCacheType CacheBackendType = "valkey"

	// HybridCacheType specifies the hybrid HNSW + Milvus backend
	HybridCacheType CacheBackendType = "hybrid"

	// QdrantCacheType specifies the Qdrant vector search engine backend
	QdrantCacheType CacheBackendType = "qdrant"
)

// EvictionPolicyType defines the available eviction policies
type EvictionPolicyType string

const (
	// FIFOEvictionPolicyType specifies the FIFO eviction policy
	FIFOEvictionPolicyType EvictionPolicyType = "fifo"

	// LRUEvictionPolicyType specifies the LRU eviction policy
	LRUEvictionPolicyType EvictionPolicyType = "lru"

	// LFUEvictionPolicyType specifies the LFU eviction policy
	LFUEvictionPolicyType EvictionPolicyType = "lfu"
)

// CacheConfig contains configuration settings shared across all cache backends
type CacheConfig struct {
	// BackendType specifies which cache implementation to use
	BackendType CacheBackendType `yaml:"backend_type"`

	// Enabled controls whether semantic caching is active
	Enabled bool `yaml:"enabled"`

	// SimilarityThreshold defines the minimum similarity score for cache hits (0.0-1.0)
	SimilarityThreshold float32 `yaml:"similarity_threshold"`

	// MaxEntries limits the number of cached entries (for in-memory backend)
	MaxEntries int `yaml:"max_entries,omitempty"`

	// TTLSeconds sets cache entry expiration time (0 disables expiration)
	TTLSeconds int `yaml:"ttl_seconds,omitempty"`

	// EvictionPolicy defines the eviction policy for in-memory cache ("fifo", "lru", "lfu")
	EvictionPolicy EvictionPolicyType `yaml:"eviction_policy,omitempty"`

	// Redis specific settings
	Redis *config.RedisConfig `yaml:"redis,omitempty"`

	// Valkey specific settings
	Valkey *config.ValkeyConfig `yaml:"valkey,omitempty"`

	// Milvus specific settings
	Milvus *config.MilvusConfig `yaml:"milvus,omitempty"`

	// Qdrant specific settings
	Qdrant *config.QdrantConfig `yaml:"qdrant,omitempty"`

	// UseHNSW enables HNSW index for faster search in memory backend
	UseHNSW bool `yaml:"use_hnsw,omitempty"`

	// HNSWM is the number of bi-directional links per node (default: 16)
	HNSWM int `yaml:"hnsw_m,omitempty"`

	// HNSWEfConstruction is the size of dynamic candidate list during construction (default: 200)
	HNSWEfConstruction int `yaml:"hnsw_ef_construction,omitempty"`

	// Hybrid cache specific settings
	MaxMemoryEntries int `yaml:"max_memory_entries,omitempty"` // Max entries in HNSW for hybrid cache

	// EmbeddingModel specifies which embedding model to use
	// Options: "bert" (default), "qwen3", "gemma", "mmbert", "multimodal"
	EmbeddingModel string `yaml:"embedding_model,omitempty"`
}

package cache

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"sync"

	"github.com/openai/openai-go"
)

// extractUserContent returns the text portion of a user message's content.
// Handles both plain string and multimodal content array variants via the
// official openai-go SDK union type.
func extractUserContent(content openai.ChatCompletionUserMessageParamContentUnion) string {
	if content.OfString.Value != "" {
		return content.OfString.Value
	}
	var result string
	for _, part := range content.OfArrayOfContentParts {
		if part.OfText != nil {
			result += part.OfText.Text
		}
	}
	return result
}

// ExtractQueryFromOpenAIRequest parses an OpenAI request using the official
// openai-go SDK types and extracts the user query (last user message text)
// along with the model name.
func ExtractQueryFromOpenAIRequest(requestBody []byte) (string, string, error) {
	var req openai.ChatCompletionNewParams
	if err := json.Unmarshal(requestBody, &req); err != nil {
		return "", "", fmt.Errorf("invalid request body: %w", err)
	}

	var userMessages []string
	for _, msg := range req.Messages {
		if msg.OfUser != nil {
			text := extractUserContent(msg.OfUser.Content)
			if text != "" {
				userMessages = append(userMessages, text)
			}
		}
	}

	query := ""
	if len(userMessages) > 0 {
		query = userMessages[len(userMessages)-1]
	}

	return req.Model, query, nil
}

// scopeNamespaceRepeat controls how many times the user namespace token is
// repeated in the scoped prefix. Repeating the token amplifies its weight in
// the embedding so that queries from different users land in distinct regions
// of the vector space, even when the original question text is identical.
const scopeNamespaceRepeat = 3

// ScopeQueryToUser adds a deterministic user namespace to the cache query.
// If userID is empty, the original query is returned unchanged for backward compatibility.
func ScopeQueryToUser(query string, userID string) string {
	return ScopeQueryToNamespace(query, strings.TrimSpace(userID))
}

// ScopeQueryToNamespace adds a deterministic, hard cache namespace while
// preserving semantic similarity within that namespace. Callers may compose
// recipe and user identity into namespaceID; backends compare only its HMAC,
// so raw tenant or profile names never enter storage.
func ScopeQueryToNamespace(query string, namespaceID string) string {
	normalizedNamespace := strings.TrimSpace(namespaceID)
	if normalizedNamespace == "" || query == "" {
		return query
	}

	namespace := userScopeNamespace(normalizedNamespace)
	tokens := make([]string, scopeNamespaceRepeat)
	for i := range tokens {
		tokens[i] = namespace
	}
	// Single-line prefix so log/trace consumers never see raw newlines from user text.
	return fmt.Sprintf("%s%s %s", cacheScopePrefix, strings.Join(tokens, " "), query)
}

// cacheScopePrefix is the marker ScopeQueryToUser writes before the repeated
// user namespace tokens. Backends use it to recover the namespace for a hard
// scope check (see CacheScopeNamespaceOf / SameCacheScope).
const cacheScopePrefix = "cache-scope "

// CacheScopeNamespaceOf returns the user-scope namespace embedded in a scoped
// query, or "" if the query is unscoped (the global/anonymous scope).
// ScopeQueryToUser formats scoped queries as
// "cache-scope <ns> <ns> <ns> <query>", so the namespace is the first
// whitespace-delimited token after the prefix.
func CacheScopeNamespaceOf(query string) string {
	if !strings.HasPrefix(query, cacheScopePrefix) {
		return ""
	}
	rest := query[len(cacheScopePrefix):]
	if i := strings.IndexByte(rest, ' '); i >= 0 {
		return rest[:i]
	}
	return rest
}

// SameCacheScope reports whether two queries belong to the same user scope.
// It is a HARD equality check on the namespace, independent of embedding
// similarity: a cache backend must require it before returning a hit so one
// user can never receive another user's cached response (the embedding prefix
// alone does not separate users reliably for long queries). Two unscoped
// queries share the empty global scope; a scoped query never matches an
// unscoped one.
//
// This is a convenience helper for backends that compare two raw queries
// (e.g. Redis/Milvus/Qdrant/Valkey, when they adopt the gate). The in-memory
// search path intentionally does NOT use it: it recovers the requester's
// namespace once via CacheScopeNamespaceOf and compares that against each
// candidate, instead of re-parsing the full query on both sides per entry.
func SameCacheScope(a, b string) bool {
	return CacheScopeNamespaceOf(a) == CacheScopeNamespaceOf(b)
}

var (
	userScopeSecretOnce   sync.Once
	cachedUserScopeSecret string
)

func userScopeNamespace(userID string) string {
	// Use a keyed construction (HMAC-SHA256) to avoid exposing a plain hash
	// of the userID, which is vulnerable to offline guessing attacks when
	// user IDs are predictable (e.g., emails, incremental IDs).
	//
	// The secret key is expected to be provided via environment variable
	// USER_SCOPE_NAMESPACE_SECRET so that it is not hard-coded in source
	// and can be managed per deployment.
	userScopeSecretOnce.Do(func() {
		cachedUserScopeSecret = os.Getenv("USER_SCOPE_NAMESPACE_SECRET")
	})
	secret := cachedUserScopeSecret
	if secret != "" {
		mac := hmac.New(sha256.New, []byte(secret))
		_, _ = mac.Write([]byte(userID))
		sum := mac.Sum(nil)
		return fmt.Sprintf("%x", sum[:8])
	}

	// Fallback to the previous behavior if no secret is configured, to avoid
	// breaking existing deployments. For production use, configuring a secret
	// is strongly recommended.
	digest := sha256.Sum256([]byte(userID))
	return fmt.Sprintf("%x", digest[:8])
}

const defaultEmbeddingModel = "bert"

// normalizeEmbeddingModel normalizes the embedding model name by trimming whitespace and converting to lowercase.
// If the resulting model name is empty, it returns "bert" as the default embedding model.
func normalizeEmbeddingModel(model string) string {
	normalized := strings.ToLower(strings.TrimSpace(model))
	if normalized == "" {
		return defaultEmbeddingModel
	}
	return normalized
}

func semanticCacheEmbeddingDimension(configured int, embeddingModel string) int {
	if configured > 0 {
		return configured
	}

	switch normalizeEmbeddingModel(embeddingModel) {
	case "qwen3":
		return 1024
	case "gemma":
		return 768
	case "mmbert":
		return 768
	case "multimodal":
		return 384
	default:
		return 384
	}
}

//go:build !windows && cgo

package cache

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"time"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/metrics"
)

const (
	// Buffer pool limits to prevent memory bloat
	maxVisitedMapSize     = 1000 // Maximum size for visited map before discarding buffer
	maxCandidatesCapacity = 200  // Maximum capacity for candidates heap before discarding buffer
	maxResultsCapacity    = 200  // Maximum capacity for results heap before discarding buffer
	maxHNSWLayers         = 16   // Maximum number of layers in HNSW index
)

// searchBuffers holds reusable buffers for HNSW search to reduce GC pressure
type searchBuffers struct {
	visited    map[int]bool
	candidates *minHeap
	results    *maxHeap
}

// Global pool for search buffers (reduces allocations)
var searchBufferPool = sync.Pool{
	New: func() interface{} {
		return &searchBuffers{
			visited:    make(map[int]bool, 100),
			candidates: newMinHeap(),
			results:    newMaxHeap(),
		}
	},
}

// getSearchBuffers gets reusable buffers from pool
func getSearchBuffers() *searchBuffers {
	buf := searchBufferPool.Get().(*searchBuffers)
	// Clear maps and heaps for reuse
	clear(buf.visited)
	buf.candidates.data = buf.candidates.data[:0]
	buf.results.data = buf.results.data[:0]
	return buf
}

// putSearchBuffers returns buffers to pool
func putSearchBuffers(buf *searchBuffers) {
	// Don't return to pool if buffers grew too large (avoid memory bloat)
	if len(buf.visited) > maxVisitedMapSize || cap(buf.candidates.data) > maxCandidatesCapacity || cap(buf.results.data) > maxResultsCapacity {
		return
	}
	searchBufferPool.Put(buf)
}

// HybridCache combines in-memory HNSW index with external Milvus storage
// Architecture:
//   - In-memory: HNSW index with ALL embeddings (for fast O(log n) search)
//   - Milvus: ALL documents (fetched by ID after search)
//
// This provides fast search while supporting millions of entries without storing docs in memory
type HybridCache struct {
	SimilarityTracker // embedded — provides LastSimilarity()
	// In-memory components (search only)
	hnswIndex        *HNSWIndex
	embeddings       [][]float32
	idMap            map[int]string // Entry index → Milvus ID
	hnswNeedsRebuild bool           // true while the HNSW graph is stale after an eviction (rebuilt on next add)

	// External storage (all documents)
	milvusCache *MilvusCache

	// Configuration
	similarityThreshold float32
	maxMemoryEntries    int // Max entries in HNSW index
	ttlSeconds          int
	enabled             bool

	// Statistics
	hitCount   int64
	missCount  int64
	evictCount int64

	// Concurrency control
	mu sync.RWMutex

	// Background TTL reclamation: drops in-memory entries that Milvus has
	// already expired so the index tracks the live working set rather than the
	// all-time high-water mark. See issue #2288.
	reclaimTicker *time.Ticker
	stopReclaim   chan struct{}
	reclaimDone   chan struct{} // closed by the reclaim goroutine on exit; lets stop block until it has returned
	closeOnce     sync.Once
	reclaimFn     func(context.Context) error // defaults to RebuildFromMilvus; overridable in tests
}

// HybridCacheOptions contains configuration for the hybrid cache
type HybridCacheOptions struct {
	// Core settings
	Enabled             bool
	SimilarityThreshold float32
	TTLSeconds          int

	// HNSW settings
	MaxMemoryEntries   int // Max entries in HNSW (default: 100,000)
	HNSWM              int // HNSW M parameter
	HNSWEfConstruction int // HNSW efConstruction parameter

	// Milvus settings
	Milvus *config.MilvusConfig

	// Embedding settings
	EmbeddingModel string // "bert", "qwen3", "gemma", "mmbert", or "multimodal"

	// (Deprecated) Milvus settings configuration path
	MilvusConfigPath string

	// Startup settings
	DisableRebuildOnStartup bool // Skip rebuilding HNSW index from Milvus on startup (default: false, meaning rebuild IS enabled)
}

// NewHybridCache creates a new hybrid cache instance
func NewHybridCache(options HybridCacheOptions) (*HybridCache, error) {
	logging.ComponentEvent("cache", "hybrid_cache_init_started", map[string]interface{}{
		"enabled":              options.Enabled,
		"max_memory_entries":   options.MaxMemoryEntries,
		"similarity_threshold": options.SimilarityThreshold,
		"ttl_seconds":          options.TTLSeconds,
		"rebuild_on_startup":   !options.DisableRebuildOnStartup,
	})

	if !options.Enabled {
		logging.ComponentDebugEvent("cache", "hybrid_cache_init_skipped", map[string]interface{}{
			"reason":  "disabled",
			"enabled": false,
		})
		return &HybridCache{
			enabled: false,
		}, nil
	}

	// Initialize Milvus backend
	milvusCache, err := NewMilvusCache(milvusCacheOptionsFromHybridOptions(options))
	if err != nil {
		return nil, fmt.Errorf("failed to initialize Milvus backend: %w", err)
	}

	// Set defaults
	if options.MaxMemoryEntries <= 0 {
		options.MaxMemoryEntries = 100000 // Default: 100K entries in memory
	}
	if options.HNSWM <= 0 {
		options.HNSWM = 16
	}
	if options.HNSWEfConstruction <= 0 {
		options.HNSWEfConstruction = 200
	}

	// Initialize HNSW index
	hnswIndex := newHNSWIndex(options.HNSWM, options.HNSWEfConstruction)

	cache := &HybridCache{
		hnswIndex:           hnswIndex,
		embeddings:          make([][]float32, 0, options.MaxMemoryEntries),
		idMap:               make(map[int]string),
		milvusCache:         milvusCache,
		similarityThreshold: options.SimilarityThreshold,
		maxMemoryEntries:    options.MaxMemoryEntries,
		ttlSeconds:          options.TTLSeconds,
		enabled:             true,
	}

	logging.ComponentEvent("cache", "hybrid_cache_initialized", map[string]interface{}{
		"hnsw_m":               options.HNSWM,
		"hnsw_ef_construction": options.HNSWEfConstruction,
		"max_memory_entries":   options.MaxMemoryEntries,
		"similarity_threshold": options.SimilarityThreshold,
		"ttl_seconds":          options.TTLSeconds,
		"rebuild_on_startup":   !options.DisableRebuildOnStartup,
	})

	// Rebuild HNSW index from Milvus on startup (enabled by default)
	// This ensures the in-memory index is populated after a restart
	// Set DisableRebuildOnStartup=true to skip this step (not recommended for production)
	if !options.DisableRebuildOnStartup {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
		defer cancel()

		if err := cache.RebuildFromMilvus(ctx); err != nil {
			logging.ComponentWarnEvent("cache", "hybrid_cache_rebuild_failed", map[string]interface{}{
				"source":      "startup",
				"error":       err.Error(),
				"empty_index": true,
			})
			// Don't fail initialization, just log warning and continue with empty index
		}

		// Start periodic TTL reclamation (reuses the same rebuild path). Gated
		// on the rebuild mechanism being enabled so the DisableRebuildOnStartup
		// opt-out also suppresses the recurring Milvus re-query.
		cache.startBackgroundReclaim()
	} else {
		logging.ComponentWarnEvent("cache", "hybrid_cache_rebuild_skipped", map[string]interface{}{
			"source":      "startup",
			"reason":      "disabled_on_startup",
			"empty_index": true,
		})
	}

	return cache, nil
}

func milvusCacheOptionsFromHybridOptions(options HybridCacheOptions) MilvusCacheOptions {
	milvusOptions := MilvusCacheOptions{
		Enabled:             true,
		SimilarityThreshold: options.SimilarityThreshold,
		TTLSeconds:          options.TTLSeconds,
		EmbeddingModel:      options.EmbeddingModel,
	}

	if options.Milvus != nil {
		milvusOptions.Config = options.Milvus
		return milvusOptions
	}

	milvusOptions.ConfigPath = options.MilvusConfigPath
	return milvusOptions
}

func (h *HybridCache) generateEmbedding(text string) ([]float32, error) {
	if h.milvusCache == nil {
		return nil, fmt.Errorf("milvus cache is not initialized")
	}

	return h.milvusCache.getEmbedding(text)
}

// IsEnabled returns whether the cache is active
func (h *HybridCache) IsEnabled() bool {
	return h.enabled
}

// CheckConnection verifies the cache backend connection is healthy
// For hybrid cache, this checks the Milvus connection
func (h *HybridCache) CheckConnection() error {
	if !h.enabled {
		return nil
	}

	if h.milvusCache == nil {
		return fmt.Errorf("milvus cache is not initialized")
	}

	// Delegate to Milvus cache connection check
	return h.milvusCache.CheckConnection()
}

// RebuildFromMilvus rebuilds the in-memory HNSW index from persistent Milvus storage
// This is called on startup to recover the index after a restart
func (h *HybridCache) RebuildFromMilvus(ctx context.Context) error {
	if !h.enabled {
		return nil
	}

	start := time.Now()
	logging.ComponentEvent("cache", "hybrid_cache_rebuild_started", map[string]interface{}{
		"max_memory_entries": h.maxMemoryEntries,
	})

	// Query all entries from Milvus
	requestIDs, embeddings, err := h.milvusCache.GetAllEntries(ctx)
	if err != nil {
		return fmt.Errorf("failed to get entries from Milvus: %w", err)
	}

	if len(requestIDs) == 0 {
		logging.ComponentEvent("cache", "hybrid_cache_rebuild_completed", map[string]interface{}{
			"entries_loaded":     0,
			"entries_available":  0,
			"duration_seconds":   time.Since(start).Seconds(),
			"entries_per_second": 0.0,
			"empty":              true,
			"truncated":          false,
		})
		return nil
	}

	// Lock for the entire rebuild process
	h.mu.Lock()
	defer h.mu.Unlock()

	// Clear existing index (full rebuild from scratch satisfies any deferred rebuild).
	loadLimit := min(len(embeddings), h.maxMemoryEntries)
	h.embeddings = make([][]float32, 0, loadLimit)
	h.idMap = make(map[int]string, loadLimit)
	h.hnswIndex = newHNSWIndex(h.hnswIndex.M, h.hnswIndex.efConstruction)
	h.hnswNeedsRebuild = false

	// Rebuild HNSW index with progress logging
	batchSize := 1000
	for i, embedding := range embeddings {
		// Check memory limits
		if len(h.embeddings) >= h.maxMemoryEntries {
			logging.ComponentWarnEvent("cache", "hybrid_cache_rebuild_truncated", map[string]interface{}{
				"max_memory_entries": h.maxMemoryEntries,
				"entries_loaded":     i,
				"entries_available":  len(embeddings),
			})
			break
		}

		// Add to HNSW
		entryIndex := len(h.embeddings)
		h.embeddings = append(h.embeddings, embedding)
		h.idMap[entryIndex] = requestIDs[i]
		h.addNodeHybrid(entryIndex, embedding)

		// Progress logging for large datasets
		if (i+1)%batchSize == 0 {
			elapsed := time.Since(start)
			rate := 0.0
			if elapsed.Seconds() > 0 {
				rate = float64(i+1) / elapsed.Seconds()
			}
			remaining := len(embeddings) - (i + 1)
			etaSeconds := 0.0
			if rate > 0 {
				etaSeconds = float64(remaining) / rate
			}
			logging.ComponentDebugEvent("cache", "hybrid_cache_rebuild_progress", map[string]interface{}{
				"entries_loaded":     i + 1,
				"entries_available":  len(embeddings),
				"progress_percent":   float64(i+1) / float64(len(embeddings)) * 100,
				"entries_per_second": rate,
				"eta_seconds":        etaSeconds,
			})
		}
	}

	elapsed := time.Since(start)
	rate := 0.0
	if elapsed.Seconds() > 0 {
		rate = float64(len(h.embeddings)) / elapsed.Seconds()
	}
	logging.ComponentEvent("cache", "hybrid_cache_rebuild_completed", map[string]interface{}{
		"entries_loaded":     len(h.embeddings),
		"entries_available":  len(embeddings),
		"duration_seconds":   elapsed.Seconds(),
		"entries_per_second": rate,
		"empty":              len(h.embeddings) == 0,
		"truncated":          len(h.embeddings) < len(embeddings),
	})

	metrics.UpdateCacheEntries("hybrid", len(h.embeddings))

	return nil
}

// AddPendingRequest stores a request awaiting its response
func (h *HybridCache) AddPendingRequest(requestID string, model string, query string, requestBody []byte, ttlSeconds int) error {
	start := time.Now()

	if !h.enabled {
		return nil
	}

	// Handle TTL=0: skip caching entirely
	if ttlSeconds == 0 {
		logging.Debugf("HybridCache.AddPendingRequest: skipping cache (ttl_seconds=0)")
		return nil
	}

	// Generate embedding
	embedding, err := h.generateEmbedding(query)
	if err != nil {
		metrics.RecordCacheOperation("hybrid", "add_pending", "error", time.Since(start).Seconds())
		return fmt.Errorf("failed to generate embedding: %w", err)
	}

	// Store in Milvus (write-through)
	if err := h.milvusCache.AddPendingRequest(requestID, model, query, requestBody, ttlSeconds); err != nil {
		metrics.RecordCacheOperation("hybrid", "add_pending", "error", time.Since(start).Seconds())
		return fmt.Errorf("milvus add pending failed: %w", err)
	}

	// Add to in-memory HNSW index
	h.mu.Lock()
	defer h.mu.Unlock()

	// Check if we need to evict
	if len(h.embeddings) >= h.maxMemoryEntries {
		h.evictOneUnsafe()
	}

	// Add to HNSW
	entryIndex := len(h.embeddings)
	h.embeddings = append(h.embeddings, embedding)
	h.idMap[entryIndex] = requestID
	h.addNodeHybridOrRebuild(entryIndex, embedding)

	logging.Debugf("HybridCache.AddPendingRequest: added to HNSW index=%d, milvusID=%s, ttl=%d",
		entryIndex, requestID, ttlSeconds)

	metrics.RecordCacheOperation("hybrid", "add_pending", "success", time.Since(start).Seconds())
	metrics.UpdateCacheEntries("hybrid", len(h.embeddings))

	return nil
}

// UpdateWithResponse completes a pending request with its response
func (h *HybridCache) UpdateWithResponse(requestID string, responseBody []byte, ttlSeconds int) error {
	start := time.Now()

	if !h.enabled {
		return nil
	}

	// Update in Milvus
	if err := h.milvusCache.UpdateWithResponse(requestID, responseBody, ttlSeconds); err != nil {
		metrics.RecordCacheOperation("hybrid", "update_response", "error", time.Since(start).Seconds())
		return fmt.Errorf("milvus update failed: %w", err)
	}

	// HNSW index already has the embedding, no update needed there

	logging.Debugf("HybridCache.UpdateWithResponse: updated milvusID=%s, ttl=%d", requestID, ttlSeconds)
	metrics.RecordCacheOperation("hybrid", "update_response", "success", time.Since(start).Seconds())

	return nil
}

// AddEntry stores a complete request-response pair
func (h *HybridCache) AddEntry(requestID string, model string, query string, requestBody, responseBody []byte, ttlSeconds int) error {
	start := time.Now()

	if !h.enabled {
		return nil
	}

	// Handle TTL=0: skip caching entirely
	if ttlSeconds == 0 {
		logging.Debugf("HybridCache.AddEntry: skipping cache (ttl_seconds=0)")
		return nil
	}

	// Generate embedding
	embedding, err := h.generateEmbedding(query)
	if err != nil {
		metrics.RecordCacheOperation("hybrid", "add_entry", "error", time.Since(start).Seconds())
		return fmt.Errorf("failed to generate embedding: %w", err)
	}

	// Store in Milvus (write-through)
	if err := h.milvusCache.AddEntry(requestID, model, query, requestBody, responseBody, ttlSeconds); err != nil {
		metrics.RecordCacheOperation("hybrid", "add_entry", "error", time.Since(start).Seconds())
		return fmt.Errorf("milvus add entry failed: %w", err)
	}

	// Add to in-memory HNSW index
	h.mu.Lock()
	defer h.mu.Unlock()

	// Check if we need to evict
	if len(h.embeddings) >= h.maxMemoryEntries {
		h.evictOneUnsafe()
	}

	// Add to HNSW
	entryIndex := len(h.embeddings)
	h.embeddings = append(h.embeddings, embedding)
	h.idMap[entryIndex] = requestID
	h.addNodeHybridOrRebuild(entryIndex, embedding)

	logging.Debugf("HybridCache.AddEntry: added to HNSW index=%d, milvusID=%s, ttl=%d",
		entryIndex, requestID, ttlSeconds)
	logging.LogEvent("hybrid_cache_entry_added", map[string]interface{}{
		"backend": "hybrid",
		"query":   query,
		"model":   model,
		"in_hnsw": true,
	})

	metrics.RecordCacheOperation("hybrid", "add_entry", "success", time.Since(start).Seconds())
	metrics.UpdateCacheEntries("hybrid", len(h.embeddings))

	return nil
}

// AddEntriesBatch stores multiple request-response pairs efficiently
func (h *HybridCache) AddEntriesBatch(entries []CacheEntry) error {
	start := time.Now()

	if !h.enabled {
		return nil
	}

	if len(entries) == 0 {
		return nil
	}

	logging.Debugf("HybridCache.AddEntriesBatch: adding %d entries in batch", len(entries))

	// Generate all embeddings first
	embeddings := make([][]float32, len(entries))
	for i, entry := range entries {
		embedding, err := h.generateEmbedding(entry.Query)
		if err != nil {
			metrics.RecordCacheOperation("hybrid", "add_entries_batch", "error", time.Since(start).Seconds())
			return fmt.Errorf("failed to generate embedding for entry %d: %w", i, err)
		}
		embeddings[i] = embedding
	}

	// Store all in Milvus at once (write-through)
	if err := h.milvusCache.AddEntriesBatch(entries); err != nil {
		metrics.RecordCacheOperation("hybrid", "add_entries_batch", "error", time.Since(start).Seconds())
		return fmt.Errorf("milvus batch add failed: %w", err)
	}

	// Add all to in-memory HNSW index
	h.mu.Lock()
	defer h.mu.Unlock()

	for i, entry := range entries {
		// Check if we need to evict
		if len(h.embeddings) >= h.maxMemoryEntries {
			h.evictOneUnsafe()
		}

		// Add to HNSW
		entryIndex := len(h.embeddings)
		h.embeddings = append(h.embeddings, embeddings[i])
		h.idMap[entryIndex] = entry.RequestID
		h.addNodeHybridOrRebuild(entryIndex, embeddings[i])
	}

	elapsed := time.Since(start)
	logging.Debugf("HybridCache.AddEntriesBatch: added %d entries in %v (%.0f entries/sec)",
		len(entries), elapsed, float64(len(entries))/elapsed.Seconds())
	logging.LogEvent("hybrid_cache_entries_added", map[string]interface{}{
		"backend": "hybrid",
		"count":   len(entries),
		"in_hnsw": true,
	})

	metrics.RecordCacheOperation("hybrid", "add_entries_batch", "success", elapsed.Seconds())
	metrics.UpdateCacheEntries("hybrid", len(h.embeddings))

	return nil
}

// Flush forces Milvus to persist all buffered data to disk
func (h *HybridCache) Flush() error {
	if !h.enabled {
		return nil
	}

	return h.milvusCache.Flush()
}

// Close releases all resources
func (h *HybridCache) Close() error {
	if !h.enabled {
		return nil
	}

	// Stop the background reclaim goroutine before taking the write lock. This
	// is ordered (not locked) on purpose: stopBackgroundReclaim blocks until the
	// goroutine has exited, and an in-flight reclaim pass needs h.mu to finish,
	// so we must release the lock to it first. By the time we acquire the write
	// lock below, no reclaim pass can still be running — which is what makes the
	// subsequent nil-out of embeddings/idMap/hnswIndex safe (no use-after-close).
	h.stopBackgroundReclaim()

	h.mu.Lock()
	defer h.mu.Unlock()

	// Close Milvus connection
	if h.milvusCache != nil {
		if err := h.milvusCache.Close(); err != nil {
			logging.Debugf("HybridCache.Close: Milvus close error: %v", err)
		}
	}

	// Clear in-memory structures
	h.embeddings = nil
	h.idMap = nil
	h.hnswIndex = nil

	metrics.UpdateCacheEntries("hybrid", 0)

	return nil
}

// GetStats returns cache statistics
func (h *HybridCache) GetStats() CacheStats {
	h.mu.RLock()
	defer h.mu.RUnlock()

	hits := atomic.LoadInt64(&h.hitCount)
	misses := atomic.LoadInt64(&h.missCount)
	total := hits + misses

	var hitRatio float64
	if total > 0 {
		hitRatio = float64(hits) / float64(total)
	}

	return CacheStats{
		TotalEntries: len(h.embeddings),
		HitCount:     hits,
		MissCount:    misses,
		HitRatio:     hitRatio,
	}
}

// Helper methods

// evictOneUnsafe removes one entry from HNSW index (must hold write lock)
func (h *HybridCache) evictOneUnsafe() {
	if len(h.embeddings) == 0 {
		return
	}

	// Simple FIFO eviction: remove oldest entry (index 0)
	victimIdx := 0

	// Get milvusID before removing from map (for logging)
	milvusID := h.idMap[victimIdx]

	// Remove the embedding from the slice
	h.embeddings = h.embeddings[1:]

	// Rebuild idMap with adjusted indices (all indices shift down by 1)
	newIDMap := make(map[int]string, len(h.idMap)-1)
	for idx, id := range h.idMap {
		if idx > victimIdx {
			newIDMap[idx-1] = id // Shift index down
		}
		// Skip victimIdx (it's being evicted)
	}
	h.idMap = newIDMap

	// Eviction shifts every entry index down, so the whole graph is stale. Mark
	// for rebuild and defer it to the next add. Mirrors InMemoryCache.evictOne.
	h.hnswNeedsRebuild = true
	h.hnswIndex.markStale()

	atomic.AddInt64(&h.evictCount, 1)

	logging.Debugf("HybridCache.evictOne: evicted entry at index %d (milvus_id=%s), new size=%d",
		victimIdx, milvusID, len(h.embeddings))
	logging.LogEvent("hybrid_cache_evicted", map[string]interface{}{
		"backend":     "hybrid",
		"milvus_id":   milvusID,
		"hnsw_index":  victimIdx,
		"new_size":    len(h.embeddings),
		"max_entries": h.maxMemoryEntries,
	})
}

// addNodeHybridOrRebuild indexes the new entry, or rebuilds the whole graph if a
// prior eviction left it stale. Without the rebuild the graph keeps only the last
// node after eviction, degrading the cache to ~100% misses at capacity.
// Caller must hold a write lock. Mirrors InMemoryCache.addEntryToHNSWIndex.
func (h *HybridCache) addNodeHybridOrRebuild(entryIndex int, embedding []float32) {
	if h.hnswNeedsRebuild {
		h.rebuildHNSWFromEmbeddings()
		return
	}
	h.addNodeHybrid(entryIndex, embedding)
}

// rebuildHNSWFromEmbeddings rebuilds the graph from the embeddings slice, reusing
// the existing index parameters. Caller must hold a write lock. Mirrors
// InMemoryCache.rebuildHNSWIndex but sources vectors from embeddings, not entries.
func (h *HybridCache) rebuildHNSWFromEmbeddings() {
	h.hnswIndex.nodes = []*HNSWNode{}
	h.hnswIndex.nodeIndex = make(map[int]*HNSWNode)
	h.hnswIndex.entryPoint = -1
	h.hnswIndex.maxLayer = -1

	for i, embedding := range h.embeddings {
		if len(embedding) > 0 {
			h.addNodeHybrid(i, embedding)
		}
	}

	h.hnswNeedsRebuild = false
	logging.Debugf("HybridCache: HNSW index rebuilt with %d nodes", len(h.hnswIndex.nodes))
}

//go:build !windows && cgo

package cache

import (
	"fmt"
	"sync"
	"time"

	candle_binding "github.com/vllm-project/semantic-router/candle-binding"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/metrics"
)

// InMemoryCache provides a high-performance semantic cache using BERT embeddings in memory
type InMemoryCache struct {
	SimilarityTracker   // embedded — provides LastSimilarity()
	entries             []CacheEntry
	entryMap            map[string]int // requestID -> index for O(1) lookup
	mu                  sync.RWMutex
	similarityThreshold float32
	maxEntries          int
	ttlSeconds          int
	enabled             bool
	hitCount            int64
	missCount           int64
	lastCleanupTime     *time.Time
	evictionPolicy      EvictionPolicy
	evictionPolicyType  EvictionPolicyType // Track the policy type for optimized eviction

	// O(1) eviction tracking
	optimizedLRU   *LRUPolicy
	optimizedLFU   *LFUPolicy
	optimizedFIFO  *FIFOPolicy
	expirationHeap *ExpirationHeap

	hnswIndex        *HNSWIndex
	useHNSW          bool
	hnswNeedsRebuild bool   // true while the HNSW graph is stale relative to entries
	hnswEfSearch     int    // Search-time ef parameter
	embeddingModel   string // "bert", "qwen3", "gemma", "mmbert", or "multimodal"

	// embMemo deduplicates query-embedding inference: a cache-miss request
	// otherwise embeds the same query twice (lookup + pending write), so the
	// memo turns the second compute into a memory hit.
	embMemo *embeddingMemo

	// Background cleanup
	cleanupTicker *time.Ticker
	stopCleanup   chan struct{}
	closeOnce     sync.Once
}

// InMemoryCacheOptions contains configuration parameters for the in-memory cache
type InMemoryCacheOptions struct {
	SimilarityThreshold float32
	MaxEntries          int
	TTLSeconds          int
	Enabled             bool
	EvictionPolicy      EvictionPolicyType
	UseHNSW             bool   // Enable HNSW index for faster search
	HNSWM               int    // Number of bi-directional links (default: 16)
	HNSWEfConstruction  int    // Size of dynamic candidate list during construction (default: 200)
	HNSWEfSearch        int    // Size of dynamic candidate list during search (default: 50)
	EmbeddingModel      string // "bert", "qwen3", "gemma", "mmbert", or "multimodal"
}

func attachInMemoryEvictionPolicy(cache *InMemoryCache, policy EvictionPolicyType) {
	switch policy {
	case LRUEvictionPolicyType:
		cache.optimizedLRU = NewLRUPolicy()
		cache.evictionPolicy = cache.optimizedLRU
		logging.ComponentDebugEvent("cache", "inmemory_cache_eviction_policy_initialized", map[string]interface{}{
			"policy": "lru",
		})
	case LFUEvictionPolicyType:
		cache.optimizedLFU = NewLFUPolicy()
		cache.evictionPolicy = cache.optimizedLFU
		logging.ComponentDebugEvent("cache", "inmemory_cache_eviction_policy_initialized", map[string]interface{}{
			"policy": "lfu",
		})
	default: // FIFO
		cache.optimizedFIFO = NewFIFOPolicy()
		cache.evictionPolicy = cache.optimizedFIFO
		logging.ComponentDebugEvent("cache", "inmemory_cache_eviction_policy_initialized", map[string]interface{}{
			"policy": "fifo",
		})
	}
}

func attachInMemoryHNSW(cache *InMemoryCache, options InMemoryCacheOptions, efSearch int) {
	if !options.UseHNSW {
		return
	}
	M := options.HNSWM
	if M <= 0 {
		M = 16 // Default value
	}
	efConstruction := options.HNSWEfConstruction
	if efConstruction <= 0 {
		efConstruction = 200 // Default value
	}
	cache.hnswIndex = newHNSWIndex(M, efConstruction)
	logging.ComponentDebugEvent("cache", "inmemory_cache_hnsw_initialized", map[string]interface{}{
		"hnsw_m":               M,
		"hnsw_ef_construction": efConstruction,
		"hnsw_ef_search":       efSearch,
	})
}

func startInMemoryTTLCleanup(cache *InMemoryCache, options InMemoryCacheOptions) {
	if !options.Enabled || options.TTLSeconds <= 0 {
		return
	}
	cache.stopCleanup = make(chan struct{})
	cleanupInterval := time.Duration(options.TTLSeconds/2) * time.Second
	if cleanupInterval < 10*time.Second {
		cleanupInterval = 10 * time.Second // Minimum 10 seconds
	}
	cache.cleanupTicker = time.NewTicker(cleanupInterval)
	go cache.backgroundCleanup()
	logging.ComponentDebugEvent("cache", "inmemory_cache_cleanup_started", map[string]interface{}{
		"interval_seconds": cleanupInterval.Seconds(),
	})
}

// NewInMemoryCache initializes a new in-memory semantic cache instance
func NewInMemoryCache(options InMemoryCacheOptions) *InMemoryCache {
	// Set HNSW search ef parameter
	efSearch := options.HNSWEfSearch
	if efSearch <= 0 {
		efSearch = 50 // Default value
	}

	// Store the canonical model name used by embedding dispatch.
	embeddingModel := normalizeEmbeddingModel(options.EmbeddingModel)

	logging.ComponentEvent("cache", "inmemory_cache_init_started", map[string]interface{}{
		"enabled":              options.Enabled,
		"max_entries":          options.MaxEntries,
		"ttl_seconds":          options.TTLSeconds,
		"similarity_threshold": options.SimilarityThreshold,
		"eviction_policy":      options.EvictionPolicy,
		"use_hnsw":             options.UseHNSW,
		"embedding_model":      embeddingModel,
	})

	cache := &InMemoryCache{
		entries:             []CacheEntry{},
		entryMap:            make(map[string]int),
		similarityThreshold: options.SimilarityThreshold,
		maxEntries:          options.MaxEntries,
		ttlSeconds:          options.TTLSeconds,
		enabled:             options.Enabled,
		evictionPolicyType:  options.EvictionPolicy,
		expirationHeap:      NewExpirationHeap(),
		useHNSW:             options.UseHNSW,
		hnswEfSearch:        efSearch,
		embeddingModel:      embeddingModel,
		embMemo:             newEmbeddingMemo(defaultEmbeddingMemoSize),
	}

	logging.ComponentEvent("cache", "inmemory_cache_initialized", map[string]interface{}{
		"enabled":              options.Enabled,
		"max_entries":          options.MaxEntries,
		"ttl_seconds":          options.TTLSeconds,
		"similarity_threshold": options.SimilarityThreshold,
		"eviction_policy":      options.EvictionPolicy,
		"use_hnsw":             options.UseHNSW,
		"hnsw_ef_search":       efSearch,
		"embedding_model":      embeddingModel,
	})

	attachInMemoryEvictionPolicy(cache, options.EvictionPolicy)
	attachInMemoryHNSW(cache, options, efSearch)
	startInMemoryTTLCleanup(cache, options)

	return cache
}

// IsEnabled returns the current cache activation status
func (c *InMemoryCache) IsEnabled() bool {
	return c.enabled
}

// CheckConnection verifies the cache connection is healthy
// For in-memory cache, this is always healthy (no external connection)
func (c *InMemoryCache) CheckConnection() error {
	// In-memory cache has no external connection to check
	return nil
}

// generateEmbedding returns an embedding for text using the configured model,
// served from the embedding memo when the same text was embedded recently
// (e.g. the lookup + pending-write pair of a single cache-miss request).
func (c *InMemoryCache) generateEmbedding(text string) ([]float32, error) {
	if c.embMemo != nil {
		return c.embMemo.getOrCompute(text, c.computeEmbedding)
	}
	return c.computeEmbedding(text)
}

// computeEmbedding runs the configured embedding model for text (no caching).
func (c *InMemoryCache) computeEmbedding(text string) ([]float32, error) {
	modelName := c.embeddingModel

	switch modelName {
	case "qwen3":
		// Use GetEmbeddingBatched for Qwen3 with TRUE continuous batching
		// Now properly fixed to avoid CUDA context issues!
		output, err := candle_binding.GetEmbeddingBatched(text, modelName, 0)
		if err != nil {
			return nil, err
		}
		return output.Embedding, nil
	case "gemma":
		// Use GetEmbeddingWithModelType for Gemma (standard version)
		output, err := candle_binding.GetEmbeddingWithModelType(text, modelName, 0)
		if err != nil {
			return nil, err
		}
		return output.Embedding, nil
	case "mmbert":
		// Use GetEmbedding2DMatryoshka for mmBERT with 2D Matryoshka support
		// Default to layer 6 (~3.6x speedup) and dimension 256 for good balance
		output, err := candle_binding.GetEmbedding2DMatryoshka(text, modelName, 6, 256)
		if err != nil {
			return nil, err
		}
		return output.Embedding, nil
	case "multimodal":
		// Use multimodal text encoder branch (384-dim default)
		output, err := candle_binding.GetEmbeddingWithModelType(text, modelName, 384)
		if err != nil {
			return nil, err
		}
		return output.Embedding, nil
	case "bert":
		// Use traditional GetEmbedding for BERT (default)
		return candle_binding.GetEmbedding(text, 0)
	default:
		return nil, fmt.Errorf("unsupported embedding model: %s (must be 'bert', 'qwen3', 'gemma', 'mmbert', or 'multimodal')", c.embeddingModel)
	}
}

// AddPendingRequest stores a request that is awaiting its response
func (c *InMemoryCache) AddPendingRequest(
	requestID string,
	model string,
	query string,
	requestBody []byte,
	ttlSeconds int,
) error {
	start := time.Now()

	if !c.enabled {
		return nil
	}

	// Handle TTL=0: skip caching entirely
	if ttlSeconds == 0 {
		logging.Debugf("InMemoryCache.AddPendingRequest: skipping cache (ttl_seconds=0)")
		return nil
	}

	// Determine effective TTL: use provided value or fall back to cache default
	effectiveTTL := ttlSeconds
	if ttlSeconds == -1 {
		effectiveTTL = c.ttlSeconds
	}

	// Generate semantic embedding using the configured model
	embedding, err := c.generateEmbedding(query)
	if err != nil {
		metrics.RecordCacheOperation("memory", "add_pending", "error", time.Since(start).Seconds())
		return fmt.Errorf("failed to generate embedding: %w", err)
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	// Remove expired entries to maintain cache hygiene, but defer the HNSW rebuild to the insertion below if HNSW is enabled.
	c.cleanupExpiredEntriesDeferred()

	// Check if eviction is needed before adding the new entry
	if c.maxEntries > 0 && len(c.entries) >= c.maxEntries {
		c.evictOne()
	}

	// Create cache entry for the pending request
	now := time.Now()
	entry := CacheEntry{
		RequestID:    requestID,
		RequestBody:  requestBody,
		Model:        model,
		Query:        query,
		Embedding:    embedding,
		Timestamp:    now,
		LastAccessAt: now,
		HitCount:     0,
		TTLSeconds:   ttlSeconds,
	}

	// Calculate expiration time if TTL is set
	if effectiveTTL > 0 {
		entry.ExpiresAt = now.Add(time.Duration(effectiveTTL) * time.Second)
	}

	c.entries = append(c.entries, entry)
	entryIndex := len(c.entries) - 1
	c.entryMap[requestID] = entryIndex

	// Register with optimized eviction policy for O(1) eviction
	c.registerEntryWithEvictionPolicy(entryIndex, requestID)

	// Register with expiration heap for efficient TTL cleanup
	if effectiveTTL > 0 {
		c.expirationHeap.Add(requestID, entryIndex, entry.ExpiresAt)
	}

	// Add to HNSW index if enabled. Do not call c.hnswIndex.addNode directly to keep in sync with entries slice when evictions/cleanups occurred.
	c.addEntryToHNSWIndex(entryIndex, embedding)

	logging.Debugf("InMemoryCache.AddPendingRequest: added pending entry (total entries: %d, embedding_dim: %d, useHNSW: %t, ttl=%d)",
		len(c.entries), len(embedding), c.useHNSW, effectiveTTL)

	// Record metrics
	metrics.RecordCacheOperation("memory", "add_pending", "success", time.Since(start).Seconds())
	metrics.UpdateCacheEntries("memory", len(c.entries))

	return nil
}

// UpdateWithResponse completes a pending request by adding the response
func (c *InMemoryCache) UpdateWithResponse(requestID string, responseBody []byte, ttlSeconds int) error {
	start := time.Now()

	if !c.enabled {
		return nil
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	// Clean up expired entries during the update
	c.cleanupExpiredEntries()

	// Locate the pending request and complete it
	now := time.Now()
	// Fast path: use entryMap for O(1) lookup
	targetIdx := -1
	if idx, ok := c.entryMap[requestID]; ok && idx >= 0 && idx < len(c.entries) &&
		c.entries[idx].RequestID == requestID && c.entries[idx].ResponseBody == nil {
		targetIdx = idx
	}
	// Fallback to linear search if not found
	if targetIdx == -1 {
		for i, entry := range c.entries {
			if entry.RequestID == requestID && entry.ResponseBody == nil {
				targetIdx = i
				c.entryMap[requestID] = i
				break
			}
		}
	}
	// No matching pending request found
	if targetIdx == -1 {
		metrics.RecordCacheOperation("memory", "update_response", "error", time.Since(start).Seconds())
		return fmt.Errorf("no pending request found for request ID: %s", requestID)
	}

	// Complete the cache entry with the response
	c.entries[targetIdx].ResponseBody = responseBody
	c.entries[targetIdx].Timestamp = now
	c.entries[targetIdx].LastAccessAt = now
	// Update TTL if provided (ttlSeconds != -1)
	// If ttlSeconds == 0, this means we shouldn't cache - but entry already exists, so just mark as complete
	if ttlSeconds != -1 {
		c.entries[targetIdx].TTLSeconds = ttlSeconds
		if ttlSeconds > 0 {
			c.entries[targetIdx].ExpiresAt = now.Add(time.Duration(ttlSeconds) * time.Second)
			// Update expiration heap with new expiration time
			c.expirationHeap.UpdateExpiration(requestID, c.entries[targetIdx].ExpiresAt)
		}
	}

	// Record successful completion
	logging.Debugf("InMemoryCache.UpdateWithResponse: updated entry with response (response_size: %d bytes, ttl=%d)",
		len(responseBody), c.entries[targetIdx].TTLSeconds)
	metrics.RecordCacheOperation("memory", "update_response", "success", time.Since(start).Seconds())
	return nil
}

// AddEntry stores a complete request-response pair in the cache
func (c *InMemoryCache) AddEntry(
	requestID string,
	model string,
	query string,
	requestBody []byte,
	responseBody []byte,
	ttlSeconds int,
) error {
	start := time.Now()

	if !c.enabled {
		return nil
	}

	if ttlSeconds == 0 {
		logging.Debugf("InMemoryCache.AddEntry: skipping cache (ttl_seconds=0)")
		return nil
	}

	effectiveTTL := ttlSeconds
	if ttlSeconds == -1 {
		effectiveTTL = c.ttlSeconds
	}

	// Generate semantic embedding using the configured model
	embedding, err := c.generateEmbedding(query)
	if err != nil {
		metrics.RecordCacheOperation("memory", "add_entry", "error", time.Since(start).Seconds())
		return fmt.Errorf("failed to generate embedding: %w", err)
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	// Remove expired entries to maintain cache hygiene, but defer the HNSW rebuild to the insertion below if HNSW is enabled.
	c.cleanupExpiredEntriesDeferred()

	// Check if eviction is needed before adding the new entry
	if c.maxEntries > 0 && len(c.entries) >= c.maxEntries {
		c.evictOne()
	}

	now := time.Now()
	entry := CacheEntry{
		RequestID:    requestID,
		RequestBody:  requestBody,
		ResponseBody: responseBody,
		Model:        model,
		Query:        query,
		Embedding:    embedding,
		Timestamp:    now,
		LastAccessAt: now,
		HitCount:     0,
		TTLSeconds:   ttlSeconds,
	}

	// Calculate expiration time if TTL is set
	if effectiveTTL > 0 {
		entry.ExpiresAt = now.Add(time.Duration(effectiveTTL) * time.Second)
	}

	c.entries = append(c.entries, entry)
	entryIndex := len(c.entries) - 1
	c.entryMap[requestID] = entryIndex

	// Register with optimized eviction policy for O(1) eviction
	c.registerEntryWithEvictionPolicy(entryIndex, requestID)

	// Register with expiration heap for efficient TTL cleanup
	if effectiveTTL > 0 {
		c.expirationHeap.Add(requestID, entryIndex, entry.ExpiresAt)
	}

	// Add to HNSW index if enabled. Do not call c.hnswIndex.addNode directly to keep in sync with entries slice when evictions/cleanups occurred.
	c.addEntryToHNSWIndex(entryIndex, embedding)

	logging.Debugf("InMemoryCache.AddEntry: added complete entry (total entries: %d, request_size: %d, response_size: %d, useHNSW: %t, ttl=%d)",
		len(c.entries), len(requestBody), len(responseBody), c.useHNSW, effectiveTTL)
	logging.LogEvent("cache_entry_added", map[string]interface{}{
		"backend": "memory",
		"query":   query,
		"model":   model,
		"useHNSW": c.useHNSW,
	})

	// Record success metrics
	metrics.RecordCacheOperation("memory", "add_entry", "success", time.Since(start).Seconds())
	metrics.UpdateCacheEntries("memory", len(c.entries))

	return nil
}

// ===== HNSW Index Implementation =====

// rebuildHNSWIndex rebuilds the HNSW index from scratch.
// Caller must hold a write lock.
func (c *InMemoryCache) rebuildHNSWIndex() {
	if !c.useHNSW || c.hnswIndex == nil {
		c.hnswNeedsRebuild = false
		return
	}

	logging.Debugf("InMemoryCache: Rebuilding HNSW index with %d entries", len(c.entries))

	// Clear the existing index
	c.hnswIndex.nodes = []*HNSWNode{}
	c.hnswIndex.nodeIndex = make(map[int]*HNSWNode) // Clear O(1) lookup map
	c.hnswIndex.entryPoint = -1
	c.hnswIndex.maxLayer = -1

	// Rebuild by adding all entries
	for i, entry := range c.entries {
		if len(entry.Embedding) > 0 {
			c.hnswIndex.addNode(i, entry.Embedding, c.entries)
		}
	}

	logging.Debugf("InMemoryCache: HNSW index rebuilt with %d nodes", len(c.hnswIndex.nodes))
	c.hnswNeedsRebuild = false
}

