package cache

import (
	"context"
	"fmt"
	"sync/atomic"
	"time"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/metrics"
)

type candidateWithID struct {
	milvusID   string
	similarity float32
	index      int
}

// FindSimilar searches for semantically similar cached requests.
func (h *HybridCache) FindSimilar(model string, query string) ([]byte, bool, error) {
	return h.findSimilar(model, query, h.similarityThreshold, "find_similar", "HybridCache.FindSimilar")
}

// FindSimilarWithThreshold searches for semantically similar cached requests using a specific threshold.
func (h *HybridCache) FindSimilarWithThreshold(model string, query string, threshold float32) ([]byte, bool, error) {
	return h.findSimilar(model, query, threshold, "find_similar_threshold", "HybridCache.FindSimilarWithThreshold")
}

func (h *HybridCache) findSimilar(
	model string,
	query string,
	threshold float32,
	metricOp string,
	logPrefix string,
) ([]byte, bool, error) {
	start := time.Now()

	if !h.enabled {
		return nil, false, nil
	}

	logging.Debugf("%s: searching for model='%s', query=%s, threshold=%.3f",
		logPrefix, model, logging.ContentDescriptor(query), threshold)

	queryEmbedding, err := h.generateEmbedding(query)
	if err != nil {
		metrics.RecordCacheOperation("hybrid", metricOp, "error", time.Since(start).Seconds())
		return nil, false, fmt.Errorf("failed to generate embedding: %w", err)
	}

	candidatesWithIDs, totalCandidates := h.searchCandidates(queryEmbedding, threshold)
	if len(candidatesWithIDs) == 0 {
		h.recordLookupMiss(start, metricOp, logPrefix, threshold, model, totalCandidates, 0)
		return nil, false, nil
	}

	logging.Debugf("%s: HNSW returned %d candidates, %d above threshold",
		logPrefix, totalCandidates, len(candidatesWithIDs))

	responseBody, candidate, found := h.fetchResponseFromCandidates(logPrefix, model, candidatesWithIDs)
	if found {
		h.StoreSimilarity(candidate.similarity)
		h.recordLookupHit(start, metricOp, threshold, model, candidate)
		return responseBody, true, nil
	}

	// The global HNSW graph may return a nearest neighbor from another model
	// partition. Milvus owns the exact model filter, so fall back to its
	// partitioned vector search instead of returning or silently accepting the
	// wrong candidate.
	responseBody, found, err = h.milvusCache.FindSimilarWithThreshold(model, query, threshold)
	if err != nil {
		metrics.RecordCacheOperation("hybrid", metricOp, "error", time.Since(start).Seconds())
		return nil, false, err
	}
	if found {
		candidate = candidateWithID{similarity: h.milvusCache.LastSimilarity()}
		h.StoreSimilarity(candidate.similarity)
		h.recordLookupHit(start, metricOp, threshold, model, candidate)
		return responseBody, true, nil
	}

	h.recordLookupMiss(start, metricOp, logPrefix, threshold, model, totalCandidates, len(candidatesWithIDs))
	return nil, false, nil
}

func (h *HybridCache) searchCandidates(queryEmbedding []float32, threshold float32) ([]candidateWithID, int) {
	h.mu.RLock()
	candidates := h.searchKNNHybridWithThreshold(queryEmbedding, 1, 20, threshold)
	candidatesWithIDs := h.candidatesAboveThresholdLocked(candidates, threshold)
	h.mu.RUnlock()

	return candidatesWithIDs, len(candidates)
}

func (h *HybridCache) candidatesAboveThresholdLocked(candidates []searchResult, threshold float32) []candidateWithID {
	candidatesWithIDs := make([]candidateWithID, 0, len(candidates))
	for _, candidate := range candidates {
		if candidate.similarity < threshold {
			continue
		}
		if milvusID, ok := h.idMap[candidate.index]; ok {
			candidatesWithIDs = append(candidatesWithIDs, candidateWithID{
				milvusID:   milvusID,
				similarity: candidate.similarity,
				index:      candidate.index,
			})
		}
	}

	return candidatesWithIDs
}

func (h *HybridCache) fetchResponseFromCandidates(
	logPrefix string,
	model string,
	candidates []candidateWithID,
) ([]byte, candidateWithID, bool) {
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	for _, candidate := range candidates {
		fetchCtx, fetchCancel := context.WithTimeout(ctx, 2*time.Second)
		responseBody, err := h.milvusCache.GetByID(fetchCtx, candidate.milvusID, model)
		fetchCancel()
		if err != nil {
			logging.Debugf("%s: Milvus GetByID failed for %s: %v", logPrefix, candidate.milvusID, err)
			continue
		}
		if responseBody != nil {
			return responseBody, candidate, true
		}
	}

	return nil, candidateWithID{}, false
}

func (h *HybridCache) recordLookupHit(
	start time.Time,
	metricOp string,
	threshold float32,
	model string,
	candidate candidateWithID,
) {
	atomic.AddInt64(&h.hitCount, 1)
	logging.Debugf("Hybrid cache hit: similarity=%.4f (threshold=%.3f)", candidate.similarity, threshold)
	logging.LogEvent("hybrid_cache_hit", map[string]interface{}{
		"backend":    "hybrid",
		"source":     "milvus",
		"similarity": candidate.similarity,
		"threshold":  threshold,
		"model":      model,
		"latency_ms": time.Since(start).Milliseconds(),
	})
	metrics.RecordCacheOperation("hybrid", metricOp, "hit_milvus", time.Since(start).Seconds())
}

func (h *HybridCache) recordLookupMiss(
	start time.Time,
	metricOp string,
	logPrefix string,
	threshold float32,
	model string,
	totalCandidates int,
	qualifiedCandidates int,
) {
	atomic.AddInt64(&h.missCount, 1)
	if qualifiedCandidates == 0 {
		if totalCandidates > 0 {
			logging.Debugf("%s: %d candidates found but none above threshold %.3f",
				logPrefix, totalCandidates, threshold)
		} else {
			logging.Debugf("%s: no candidates found in HNSW", logPrefix)
		}
	} else {
		logging.Debugf("%s: cache miss after checking %d qualified candidates", logPrefix, qualifiedCandidates)
	}
	logging.LogEvent("hybrid_cache_miss", map[string]interface{}{
		"backend":    "hybrid",
		"threshold":  threshold,
		"model":      model,
		"candidates": qualifiedCandidates,
	})
	metrics.RecordCacheOperation("hybrid", metricOp, "miss", time.Since(start).Seconds())
}

//go:build !windows && cgo

package cache

import (
	"fmt"
	"sync/atomic"
	"time"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/metrics"
)

func embeddingDotProduct(queryEmbedding, candidate []float32) float32 {
	var dot float32
	for i := 0; i < len(queryEmbedding) && i < len(candidate); i++ {
		dot += queryEmbedding[i] * candidate[i]
	}
	return dot
}

func (c *InMemoryCache) refreshHNSWIfStaleDuringSearch() {
	if !c.hnswNeedsRebuild {
		return
	}
	logging.Debugf("InMemoryCache.FindSimilar: HNSW index marked as needing rebuild, rebuilding now")
	c.mu.RUnlock()
	c.mu.Lock()
	if c.hnswNeedsRebuild {
		c.rebuildHNSWIndex()
	}
	c.mu.Unlock()
	c.mu.RLock()
}

// entryEligible reports whether an entry may be returned as a search match for
// the requester's scope (ok), and separately whether it was skipped because it
// has expired (expired). The two search paths share it so the per-candidate
// skip logic — and the security-critical scope gate in particular — lives in
// exactly one place that neither path can silently drop.
//
// The check order is load-bearing:
//  1. entries without a stored response are not matchable;
//  2. the exact model partition drops entries owned by another model/recipe;
//  3. the hard user-scope gate (see CacheScopeNamespaceOf) drops a different
//     user's entry BEFORE the expiry check, so an out-of-scope entry never
//     counts toward expiredCount;
//  4. expired entries are not matchable but are reported via expired=true so
//     the caller can tally them.
func (c *InMemoryCache) entryEligible(entry CacheEntry, model, scopeNamespace string, now time.Time) (ok bool, expired bool) {
	if entry.ResponseBody == nil {
		return false, false
	}
	if entry.Model != model {
		return false, false
	}
	// Hard user-scope gate: never return another user's entry even if its
	// embedding is the nearest neighbor.
	if CacheScopeNamespaceOf(entry.Query) != scopeNamespace {
		return false, false
	}
	if c.isExpired(entry, now) {
		return false, true
	}
	return true, false
}

func (c *InMemoryCache) scanHNSWCandidates(
	queryEmbedding []float32,
	model string,
	scopeNamespace string,
	now time.Time,
) (bestIndex int, bestSimilarity float32, entriesChecked int, expiredCount int) {
	bestIndex = -1
	candidateIndices := c.hnswIndex.searchKNN(queryEmbedding, 10, c.hnswEfSearch, c.entries)
	for _, entryIndex := range candidateIndices {
		if entryIndex < 0 || entryIndex >= len(c.entries) {
			continue
		}
		entry := c.entries[entryIndex]
		ok, expired := c.entryEligible(entry, model, scopeNamespace, now)
		if expired {
			expiredCount++
		}
		if !ok {
			continue
		}
		dotProduct := embeddingDotProduct(queryEmbedding, entry.Embedding)
		entriesChecked++
		if bestIndex == -1 || dotProduct > bestSimilarity {
			bestSimilarity = dotProduct
			bestIndex = entryIndex
		}
	}
	logging.Debugf("InMemoryCache.FindSimilar: HNSW search checked %d candidates", len(candidateIndices))
	return bestIndex, bestSimilarity, entriesChecked, expiredCount
}

func (c *InMemoryCache) scanLinearForSimilarity(
	queryEmbedding []float32,
	model string,
	scopeNamespace string,
	now time.Time,
) (bestIndex int, bestSimilarity float32, entriesChecked int, expiredCount int) {
	bestIndex = -1
	for entryIndex, entry := range c.entries {
		ok, expired := c.entryEligible(entry, model, scopeNamespace, now)
		if expired {
			expiredCount++
		}
		if !ok {
			continue
		}
		dotProduct := embeddingDotProduct(queryEmbedding, entry.Embedding)
		entriesChecked++
		if bestIndex == -1 || dotProduct > bestSimilarity {
			bestSimilarity = dotProduct
			bestIndex = entryIndex
		}
	}
	if !c.useHNSW {
		logging.Debugf("InMemoryCache.FindSimilar: Linear search used (HNSW disabled)")
	}
	return bestIndex, bestSimilarity, entriesChecked, expiredCount
}

// FindSimilar searches for semantically similar cached requests using the default threshold
func (c *InMemoryCache) FindSimilar(model string, query string) ([]byte, bool, error) {
	return c.FindSimilarWithThreshold(model, query, c.similarityThreshold)
}

// FindSimilarWithThreshold searches for semantically similar cached requests using a specific threshold
func (c *InMemoryCache) FindSimilarWithThreshold(model string, query string, threshold float32) ([]byte, bool, error) {
	start := time.Now()

	if !c.enabled {
		logging.Debugf("InMemoryCache.FindSimilarWithThreshold: cache disabled")
		return nil, false, nil
	}
	logging.Debugf("InMemoryCache.FindSimilarWithThreshold: searching for model='%s', query=%s, threshold=%.4f",
		model, logging.ContentDescriptor(query), threshold)

	queryEmbedding, err := c.generateEmbedding(query)
	if err != nil {
		metrics.RecordCacheOperation("memory", "find_similar", "error", time.Since(start).Seconds())
		return nil, false, fmt.Errorf("failed to generate embedding: %w", err)
	}

	bestIndex, bestEntry, bestSimilarity, entriesChecked, expiredCount := c.runFindSimilarEmbeddingSearch(
		queryEmbedding,
		model,
		CacheScopeNamespaceOf(query),
	)

	return c.finishFindSimilarSearch(
		start, model, threshold,
		bestIndex, bestEntry, bestSimilarity, entriesChecked, expiredCount,
	)
}

func (c *InMemoryCache) runFindSimilarEmbeddingSearch(queryEmbedding []float32, model, scopeNamespace string) (
	bestIndex int,
	bestEntry CacheEntry,
	bestSimilarity float32,
	entriesChecked int,
	expiredCount int,
) {
	c.mu.RLock()
	now := time.Now()
	if c.useHNSW && c.hnswIndex != nil {
		c.refreshHNSWIfStaleDuringSearch()
		bestIndex, bestSimilarity, entriesChecked, expiredCount = c.scanHNSWCandidates(queryEmbedding, model, scopeNamespace, now)
	} else {
		bestIndex, bestSimilarity, entriesChecked, expiredCount = c.scanLinearForSimilarity(queryEmbedding, model, scopeNamespace, now)
	}
	if bestIndex >= 0 {
		bestEntry = c.entries[bestIndex]
	}
	c.mu.RUnlock()
	return bestIndex, bestEntry, bestSimilarity, entriesChecked, expiredCount
}

func (c *InMemoryCache) finishFindSimilarSearch(
	start time.Time,
	model string,
	threshold float32,
	bestIndex int,
	bestEntry CacheEntry,
	bestSimilarity float32,
	entriesChecked int,
	expiredCount int,
) ([]byte, bool, error) {
	if expiredCount > 0 {
		logging.Debugf("InMemoryCache: excluded %d expired entries during search (TTL: %ds)",
			expiredCount, c.ttlSeconds)
		logging.LogEvent("cache_expired_entries_found", map[string]interface{}{
			"backend":       "memory",
			"expired_count": expiredCount,
			"ttl_seconds":   c.ttlSeconds,
		})
	}

	if bestIndex < 0 {
		atomic.AddInt64(&c.missCount, 1)
		logging.Debugf("InMemoryCache.FindSimilarWithThreshold: no entries found with responses")
		metrics.RecordCacheOperation("memory", "find_similar", "miss", time.Since(start).Seconds())
		return nil, false, nil
	}

	c.StoreSimilarity(bestSimilarity)

	if bestSimilarity >= threshold {
		atomic.AddInt64(&c.hitCount, 1)

		c.mu.Lock()
		c.updateAccessInfo(bestIndex, bestEntry)
		c.mu.Unlock()

		logging.Debugf("InMemoryCache.FindSimilarWithThreshold: CACHE HIT - similarity=%.4f >= threshold=%.4f, response_size=%d bytes",
			bestSimilarity, threshold, len(bestEntry.ResponseBody))
		logging.LogEvent("cache_hit", map[string]interface{}{
			"backend":    "memory",
			"similarity": bestSimilarity,
			"threshold":  threshold,
			"model":      model,
		})
		metrics.RecordCacheOperation("memory", "find_similar", "hit", time.Since(start).Seconds())
		return bestEntry.ResponseBody, true, nil
	}

	atomic.AddInt64(&c.missCount, 1)
	logging.Debugf("InMemoryCache.FindSimilarWithThreshold: CACHE MISS - best_similarity=%.4f < threshold=%.4f (checked %d entries)",
		bestSimilarity, threshold, entriesChecked)
	logging.LogEvent("cache_miss", map[string]interface{}{
		"backend":         "memory",
		"best_similarity": bestSimilarity,
		"threshold":       threshold,
		"model":           model,
		"entries_checked": entriesChecked,
	})
	metrics.RecordCacheOperation("memory", "find_similar", "miss", time.Since(start).Seconds())
	return nil, false, nil
}

package cache

import (
	"fmt"

	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
	"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
)

// NewCacheBackend creates a cache backend instance from the provided configuration
func NewCacheBackend(config CacheConfig) (CacheBackend, error) {
	if err := ValidateCacheConfig(config); err != nil {
		return nil, fmt.Errorf("invalid cache config: %w", err)
	}

	if !config.Enabled {
		// Create a disabled cache backend
		logging.Debugf("Cache disabled - creating disabled in-memory cache backend")
		return NewInMemoryCache(InMemoryCacheOptions{
			Enabled: false,
		}), nil
	}

	switch config.BackendType {
	case InMemoryCacheType, "":
		// Use in-memory cache as the default backend
		logging.Debugf("Creating in-memory cache backend - MaxEntries: %d, TTL: %ds, Threshold: %.3f, EmbeddingModel: %s, UseHNSW: %t",
			config.MaxEntries, config.TTLSeconds, config.SimilarityThreshold, config.EmbeddingModel, config.UseHNSW)

		options := InMemoryCacheOptions{
			Enabled:             config.Enabled,
			SimilarityThreshold: config.SimilarityThreshold,
			MaxEntries:          config.MaxEntries,
			TTLSeconds:          config.TTLSeconds,
			EvictionPolicy:      config.EvictionPolicy,
			UseHNSW:             config.UseHNSW,
			HNSWM:               config.HNSWM,
			HNSWEfConstruction:  config.HNSWEfConstruction,
			EmbeddingModel:      config.EmbeddingModel,
		}
		return NewInMemoryCache(options), nil

	case MilvusCacheType:
		logging.Debugf("Creating Milvus cache backend - Config: %v, TTL: %ds, Threshold: %.3f, EmbeddingModel: %s",
			config.Milvus, config.TTLSeconds, config.SimilarityThreshold, config.EmbeddingModel)
		return NewMilvusCache(MilvusCacheOptions{
			Enabled:             config.Enabled,
			SimilarityThreshold: config.SimilarityThreshold,
			TTLSeconds:          config.TTLSeconds,
			Config:              config.Milvus,
			EmbeddingModel:      config.EmbeddingModel,
		})

	case RedisCacheType:
		logging.Debugf("Creating Redis cache backend - Config: %v, TTL: %ds, Threshold: %.3f, EmbeddingModel: %s",
			config.Redis, config.TTLSeconds, config.SimilarityThreshold, config.EmbeddingModel)
		return NewRedisCache(RedisCacheOptions{
			Enabled:             config.Enabled,
			SimilarityThreshold: config.SimilarityThreshold,
			TTLSeconds:          config.TTLSeconds,
			Config:              config.Redis,
			EmbeddingModel:      config.EmbeddingModel,
		})

	case ValkeyCacheType:
		if config.Valkey == nil {
			return nil, fmt.Errorf("valkey configuration is required for Valkey cache backend")
		}
		logging.Debugf("Creating Valkey cache backend - Config: %v, TTL: %ds, Threshold: %.3f, EmbeddingModel: %s",
			config.Valkey, config.TTLSeconds, config.SimilarityThreshold, config.EmbeddingModel)
		options := ValkeyCacheOptions{
			Enabled:             config.Enabled,
			SimilarityThreshold: config.SimilarityThreshold,
			TTLSeconds:          config.TTLSeconds,
			Config:              config.Valkey,
			EmbeddingModel:      config.EmbeddingModel,
		}
		return NewValkeyCache(options)

	case HybridCacheType:
		logging.Debugf("Creating Hybrid cache backend - Config: %v, TTL: %ds, Threshold: %.3f, EmbeddingModel: %s",
			config.Milvus, config.TTLSeconds, config.SimilarityThreshold, config.EmbeddingModel)
		return NewHybridCache(hybridCacheOptionsFromConfig(config))

	case QdrantCacheType:
		logging.Debugf("Creating Qdrant cache backend - Config: %v, TTL: %ds, Threshold: %.3f, EmbeddingModel: %s",
			config.Qdrant, config.TTLSeconds, config.SimilarityThreshold, config.EmbeddingModel)
		return NewQdrantCache(QdrantCacheOptions{
			Enabled:             config.Enabled,
			SimilarityThreshold: config.SimilarityThreshold,
			TTLSeconds:          config.TTLSeconds,
			Config:              config.Qdrant,
			EmbeddingModel:      config.EmbeddingModel,
		})

	default:
		logging.Debugf("Unsupported cache backend type: %s", config.BackendType)
		return nil, fmt.Errorf("unsupported cache backend type: %s", config.BackendType)
	}
}

func hybridCacheOptionsFromConfig(config CacheConfig) HybridCacheOptions {
	return HybridCacheOptions{
		Enabled:             config.Enabled,
		SimilarityThreshold: config.SimilarityThreshold,
		TTLSeconds:          config.TTLSeconds,
		MaxMemoryEntries:    config.MaxMemoryEntries,
		HNSWM:               config.HNSWM,
		HNSWEfConstruction:  config.HNSWEfConstruction,
		Milvus:              config.Milvus,
		EmbeddingModel:      config.EmbeddingModel,
	}
}

// ValidateCacheConfig validates cache configuration parameters
func ValidateCacheConfig(config CacheConfig) error {
	if !config.Enabled {
		return nil
	}
	if config.SimilarityThreshold < 0.0 || config.SimilarityThreshold > 1.0 {
		return fmt.Errorf("similarity_threshold must be between 0.0 and 1.0, got: %f", config.SimilarityThreshold)
	}
	if config.TTLSeconds < 0 {
		return fmt.Errorf("ttl_seconds cannot be negative, got: %d", config.TTLSeconds)
	}
	return validateCacheBackend(config)
}

func validateCacheBackend(config CacheConfig) error {
	switch config.BackendType {
	case InMemoryCacheType, "":
		return validateInMemoryCacheConfig(config)
	case MilvusCacheType:
		if config.Milvus == nil {
			return fmt.Errorf("milvus configuration is required for Milvus cache backend")
		}
		logging.Debugf("Milvus configuration: %+v", config.Milvus)
	case RedisCacheType:
		if config.Redis == nil {
			return fmt.Errorf("redis configuration is required for Redis cache backend")
		}
	case HybridCacheType:
		if config.Milvus == nil {
			return fmt.Errorf("milvus configuration is required for hybrid cache backend")
		}
	case ValkeyCacheType:
		if config.Valkey == nil {
			return fmt.Errorf("valkey configuration is required for Valkey cache backend")
		}
	case QdrantCacheType:
		return validateQdrantCacheConfig(config.Qdrant)
	}
	return nil
}

func validateInMemoryCacheConfig(config CacheConfig) error {
	if config.MaxEntries < 0 {
		return fmt.Errorf("max_entries cannot be negative for in-memory cache, got: %d", config.MaxEntries)
	}
	switch config.EvictionPolicy {
	case "", FIFOEvictionPolicyType, LRUEvictionPolicyType, LFUEvictionPolicyType:
	default:
		return fmt.Errorf("unsupported eviction_policy: %s", config.EvictionPolicy)
	}
	return nil
}

func validateQdrantCacheConfig(cfg *config.QdrantConfig) error {
	if cfg == nil {
		return fmt.Errorf("qdrant configuration is required for Qdrant cache backend")
	}
	if cfg.Host == "" {
		return fmt.Errorf("qdrant.host is required for Qdrant cache backend")
	}
	return nil
}

// GetDefaultCacheConfig provides sensible default cache configuration values
func GetDefaultCacheConfig() CacheConfig {
	return CacheConfig{
		BackendType:         InMemoryCacheType,
		Enabled:             true,
		SimilarityThreshold: 0.8,
		MaxEntries:          1000,
		TTLSeconds:          3600,
	}
}

